-- Generated from the owner's menu-export.csv (161 items, 18 categories). Do not edit prices by hand.
create type public.stanica as enum ('kuhinja', 'pecenjara', 'sank');
create type public.jedinica as enum ('porcija', 'kom', 'kg', 'l');

create table public.kategorije (
  id text primary key,
  naziv text not null unique,
  redoslijed smallint not null
);
alter table public.kategorije enable row level security;
revoke all on table public.kategorije from public, anon, authenticated, service_role;

create table public.proizvodi (
  id uuid primary key default gen_random_uuid(),
  kategorija_id text not null references public.kategorije (id),
  naziv text not null,
  cijena numeric(10, 2) not null check (cijena >= 0),
  jedinica public.jedinica not null,
  stanica public.stanica not null,
  redoslijed smallint not null,
  aktivan boolean not null default true,
  unique (kategorija_id, naziv)
);
alter table public.proizvodi enable row level security;
revoke all on table public.proizvodi from public, anon, authenticated, service_role;


